import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target = inputs["target_positions"].copy()
    events = inputs["position_events"].copy()

    # 1. Distinct events by batch_seq (dedupe repeated deliveries)
    events = events.drop_duplicates(subset=["batch_seq"], keep="first")

    # Build initial state lookup from target_positions
    state = {}
    for row in target.itertuples(index=False):
        key = (row.account_id, row.symbol)
        state[key] = {"qty": row.qty, "price": row.price, "row_version": row.row_version}

    # 2. Replay guard: compare against ORIGINAL target row_version
    target_versions = target[["account_id", "symbol", "row_version"]].rename(
        columns={"row_version": "target_version"}
    )
    events = events.merge(target_versions, on=["account_id", "symbol"], how="left")

    mask = events["target_version"].isna() | (events["row_version"] > events["target_version"])
    events = events[mask].copy()

    # 3. Order of application: row_version, then batch_seq (within each key)
    events = events.sort_values(by=["account_id", "symbol", "row_version", "batch_seq"], kind="mergesort")

    closed = {}  # key -> closed_version

    for key, group in events.groupby(["account_id", "symbol"], sort=False):
        cur = state.get(key)  # None if no existing row
        removal_version = None

        for ev in group.itertuples(index=False):
            op = ev.op
            qty = ev.qty
            price = ev.price
            rv = ev.row_version

            if op == "D":
                if cur is not None:
                    cur = None
                    removal_version = rv
                # else: no-op, nothing changes
            elif op in ("I", "U"):
                is_zero = pd.notna(qty) and qty == 0
                if is_zero:
                    if cur is not None:
                        cur = None
                        removal_version = rv
                    # else: no-op
                else:
                    if cur is not None:
                        if op == "U" and pd.isna(price):
                            new_price = cur["price"]
                        else:
                            new_price = price
                        cur = {"qty": qty, "price": new_price, "row_version": rv}
                        removal_version = None
                    else:
                        cur = {"qty": qty, "price": price, "row_version": rv}
                        removal_version = None

        state[key] = cur
        if cur is None and removal_version is not None:
            closed[key] = removal_version
        elif cur is not None:
            # row exists -> not closed, ensure it's not lingering in closed from a prior state
            closed.pop(key, None)

    # Build new_positions output
    new_rows = []
    for key, cur in state.items():
        if cur is not None:
            acc, sym = key
            qty_val = cur["qty"]
            price_val = cur["price"]
            rv_val = cur["row_version"]
            new_rows.append(
                {
                    "account_id": int(acc),
                    "symbol": sym,
                    "qty": int(qty_val) if pd.notna(qty_val) else qty_val,
                    "price": price_val,
                    "row_version": int(rv_val),
                }
            )

    if new_rows:
        new_positions = pd.DataFrame(new_rows, columns=["account_id", "symbol", "qty", "price", "row_version"])
        new_positions = new_positions.astype(
            {"account_id": "int64", "qty": "int64", "price": "float64", "row_version": "int64"}
        )
    else:
        new_positions = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "symbol": pd.Series(dtype="object"),
                "qty": pd.Series(dtype="int64"),
                "price": pd.Series(dtype="float64"),
                "row_version": pd.Series(dtype="int64"),
            }
        )

    # Build closed_positions output
    closed_rows = []
    for key, ver in closed.items():
        acc, sym = key
        closed_rows.append({"account_id": int(acc), "symbol": sym, "closed_version": int(ver)})

    if closed_rows:
        closed_positions = pd.DataFrame(closed_rows, columns=["account_id", "symbol", "closed_version"])
        closed_positions = closed_positions.astype(
            {"account_id": "int64", "closed_version": "int64"}
        )
    else:
        closed_positions = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "symbol": pd.Series(dtype="object"),
                "closed_version": pd.Series(dtype="int64"),
            }
        )

    return {"new_positions": new_positions, "closed_positions": closed_positions}
